using Gravicode.Science.GraviNum;
using Gravicode.Science.SciNet;
using Xunit;
using static Gravicode.Science.Tests.SciNet.InterpolateAssert;

namespace Gravicode.Science.Tests.SciNet;

// Expected values: scipy 1.17.1 griddata / *NDInterpolator on 40 random points (default_rng(1)).
public class ScatteredTests
{
    private static readonly double[,] P = {{1.023643, 0.950464}, {0.288319, 0.948649}, {0.623663, 0.423326}, {1.655405, 0.409199}, {1.099187, 0.027559}, {1.507026, 0.538143}, {0.659463, 0.788429}, {0.60639, 0.453498}, {0.268083, 0.403113}, {0.40691, 0.262313}, {1.500729, 0.280409}, {0.970382, 0.980737}, {1.923314, 0.72479}, {1.082454, 0.276891}, {0.321304, 0.969925}, {1.032137, 0.115866}, {1.24698, 0.776683}, {1.226007, 0.917298}, {0.079186, 0.528589}, {0.918672, 0.06235}, {1.282656, 0.852633}, {1.185882, 0.260097}, {1.679763, 0.509496}, {1.021778, 0.75303}, {0.295844, 0.819627}, {1.366574, 0.787097}, {0.383233, 0.802364}, {0.382648, 0.081553}, {1.710454, 0.861283}, {1.753074, 0.47191}, {0.548097, 0.007092}, {1.291442, 0.719909}, {1.671138, 0.281878}, {0.430436, 0.639331}, {1.61011, 0.963671}, {0.30105, 0.482212}, {1.789432, 0.422717}, {1.179004, 0.024491}, {1.34692, 0.919089}, {1.653651, 0.88552}};
    private static readonly double[] F = [0.9500480126990483, 0.029415261292554423, 0.8968804182585282, 0.015895158783932106, -0.12480837330415777, 0.34505350504054355, 0.5143747004261245, 0.8722048959863796, 0.6066856953835209, 0.9197558269835922, -0.40736285926474136, 0.8647066403256223, 1.3346265470764613, 0.2099281798076439, 0.015324282504665887, 0.16354857739893056, 0.9586761534632326, 1.2578754178993368, 0.1574819461936816, 0.43045235837006474, 1.1806537008278748, -0.042248965772960334, 0.3593696367734685, 0.7743579649916571, 0.18943316732873075, 1.0784059854852008, 0.27653087063409687, 0.9310249309215347, 1.6112960074226217, 0.3261493120921045, 1.001087266176966, 0.8423590841722267, -0.33618849200650547, 0.5520126354606203, 1.8982307883688323, 0.5926939852931986, 0.23067685807592364, -0.3558582285047659, 1.4447630326639684, 1.6571360687950774];
    private static readonly double[,] Q = {{0.5, 0.5}, {1.2, 0.3}, {0.05, 0.9}, {1.9, 0.95}, {1.0, 0.7}, {0.33, 0.12}, {2.5, 0.5}, {1.5, 0.6}};

    [Fact]
    public void Griddata_EachMethod_MatchesScipy()
    {
        AllClose([0.8722048959863796, -0.042248965772960334, 0.029415261292554423, 1.6112960074226217, 0.7743579649916571, 0.9310249309215347, 1.3346265470764613, 0.34505350504054355], Interpolate.Griddata(P, F, Q, GriddataMethod.Nearest), 0, "nearest");
        AllClose([0.7405087025184315, 0.031674346999137834, double.NaN, double.NaN, 0.7447784454942388, double.NaN, double.NaN, 0.5507626485990491], Interpolate.Griddata(P, F, Q, GriddataMethod.Linear), 1e-12, "linear");
        AllClose([0.7790391309807266, -0.0041456241899521734, double.NaN, double.NaN, 0.7296700013135881, double.NaN, double.NaN, 0.5478999771482277], Interpolate.Griddata(P, F, Q, GriddataMethod.Cubic), 1e-12, "cubic");
        AllClose([0.7405087025184316, 0.07288375863672628, -1.0, -1.0, 0.7399902890866055, -1.0, -1.0, 0.5507670145325148], Interpolate.Griddata(P, F, Q, GriddataMethod.Linear, fillValue: -1, rescale: true), 1e-12, "linear rescaled, fill -1");
        AllClose([0.7810330495780322, 0.0007695520249251906, double.NaN, double.NaN, 0.7064466659329496, double.NaN, double.NaN, 0.543942256643684], Interpolate.Griddata(P, F, Q, GriddataMethod.Cubic, rescale: true), 1e-8, "cubic rescaled");
    }

    [Fact]
    public void CloughTocher_GradientsMatchScipy_AndInterpolatesData()
    {
        var ct = new CloughTocher2DInterpolator(P, F);
        AllClose([2.011734896122193, 0.8387730283690257, 0.30106902309156364, -1.1398789152167121, -0.22251730835367406, -0.6621682159119741, 1.0341834974134032, 3.0629058687615283, -2.9451426312767706, 1.0576602540373947, 0.2826904958747473, 3.2534204181124378, 0.8772847685140648, -1.2428628016763126, 0.25364251020585193, -0.8925912835339997, 1.7679789716581902, -0.7864163211515719, 0.9121249837235343, -0.5986093291825705, -0.23946173100001122, 2.5768152554048225, 1.8211403330723561, 0.4136570129502229, 0.9360170383325401, 3.3861073591578426, -2.2429017502429676, 1.114468136883318, 0.5314707442952111, -1.3832154414268092, -2.842288643345609, 1.1005693028595211, 0.7137084507026522, 2.462261221882312, 1.5755433231940408, 2.2385435601340107, 1.8709982535358276, -0.8979204122110346, -2.565725398877901, 0.5911770426297512, 1.1640714315174014, 2.544024958565151, -2.0763849073460507, 1.5850009591240684, 1.011862056119309, 3.267289866384329, 0.46237457595593384, 0.8011360289310064, 0.8629392416006295, -1.2060075783333106, 0.8167772310974691, 2.9994472660581777, 0.684844183981075, -1.4079412343651314, 1.0648793285537836, -0.1838531569500012, 0.7622053880648983, 3.61358778274694, 1.298757701855375, 3.0039242812614115, -0.8571330162413666, -0.47866811362723266, 0.4621523234949861, 2.533235173239216, 0.671882951037483, 2.8588430711214254, 0.8289011717316039, -1.4026067181100128, 1.0385676841331957, 3.664842064329256, 1.4557819061159971, -0.9883735235028821, 1.4716069239313023, 2.989641417839589, -2.6610733616488385, 1.5186747503159717, 1.451292290905533, 2.8239208486104364, 0.7612215385784996, 3.57979236739432], ct.Gradients.ToArray(), 1e-11, "gradients");
        AllClose(F, ct.Evaluate(P), 1e-12, "reproduces data");
        var lin = new LinearNDInterpolator(P, F);
        AllClose(F, lin.Evaluate(P), 1e-12, "linear reproduces data");
        // A linear function is reproduced exactly by both.
        var g = new double[40];
        for (var i = 0; i < 40; i++) g[i] = 2 * P[i, 0] - 3 * P[i, 1] + 0.5;
        var inside = new double[,] { { 0.5, 0.5 }, { 1.2, 0.3 }, { 1.0, 0.7 } };
        double[] exact = [0.0, 2.0, 0.4];
        AllClose(exact, new LinearNDInterpolator(P, g).Evaluate(inside), 1e-12, "linear exact");
        AllClose(exact, new CloughTocher2DInterpolator(P, g).Evaluate(inside), 1e-6, "cubic exact for linear data");
    }

    [Fact]
    public void Griddata_OneDimensional_AndVectorValues()
    {
        var p1 = new NdArray([0.3, 0.0, 1.0, 0.6, 2.0], 5, 1);
        var v1 = new NdArray([1.0, 0.0, 2.0, 1.5, 0.5], 5);
        var q1 = new NdArray([-0.5, 0.2, 0.8, 1.7, 2.5], 5, 1);
        AllClose([double.NaN, 0.6666666666666667, 1.75, 0.9500000000000002, double.NaN], Interpolate.Griddata(p1, v1, q1, GriddataMethod.Linear).ToArray(), 1e-14, "1-D linear");
        AllClose([0.0, 1.0, 1.5, 0.5, 0.5], Interpolate.Griddata(p1, v1, q1, GriddataMethod.Nearest).ToArray(), 0, "1-D nearest");
        AllClose([double.NaN, 0.747534698259336, 1.7743271221532093, 1.6235507246376808, double.NaN], Interpolate.Griddata(p1, v1, q1, GriddataMethod.Cubic).ToArray(), 1e-12, "1-D cubic");
        var vv = new double[80];
        for (var i = 0; i < 40; i++) { vv[2 * i] = F[i]; vv[2 * i + 1] = -2 * F[i]; }
        var r = new LinearNDInterpolator(NdArray.FromArray(P), new NdArray(vv, 40, 2)).Evaluate(NdArray.FromArray(Q));
        Assert.Equal([8, 2], r.Shape.ToArray());
        var s = Interpolate.Griddata(P, F, Q, GriddataMethod.Linear);
        for (var i = 0; i < 8; i++) { Close(s[i], r.ToArray()[2 * i], 1e-14, "c0"); Close(-2 * s[i], r.ToArray()[2 * i + 1], 1e-14, "c1"); }
    }
}
